    UPDATE dbo.AgMcpToolVersion
    SET ServerId = CONVERT(uniqueidentifier, N'4ca452c6-088b-421d-91ed-9f9f418b488b'), HistoryOrdinal = 4, CurrentOrdinal = NULL,
        Name = N'get_supplier_import_template', Description = CAST(N'' AS nvarchar(max)) + N'工具名称：get_supplier_import_template' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'功能描述：  ' + NCHAR(13) + NCHAR(10) + N'用于获取供应商批量导入所需的 **标准 Excel 模板文件**。调用后，系统将生成或返回一个预定义的空模板（含字段说明、格式规范、下拉选项等），并返回该文件的唯一标识 `fileId`，供前端用于下载或展示。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'输入参数：  ' + NCHAR(13) + NCHAR(10) + N'- 无（无需任何输入参数）。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'行为说明：  ' + NCHAR(13) + NCHAR(10) + N'- 工具将返回一个有效的 `files`，对应一个可下载的 Excel 文件（如 .xlsx 格式）；  ' + NCHAR(13) + NCHAR(10) + N'- 该模板包含供应商创建所需的必填字段（如供应商编号、名称、联系人、税号、银行账号等）及填写说明；  ' + NCHAR(13) + NCHAR(10) + N'- 每次调用应返回**最新版本**的模板，确保与当前系统字段一致；  ' + NCHAR(13) + NCHAR(10) + N'- 返回的 `files` 应具备临时可访问权限（如 24 小时有效），供前端直接下载。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'触发条件：  ' + NCHAR(13) + NCHAR(10) + N'- 用户表达“下载模板”“获取导入模板”“要一个供应商Excel格式”“怎么批量导入供应商”等意图时调用；  ' + NCHAR(13) + NCHAR(10) + N'- 无需用户指定供应商信息，本工具与具体业务数据无关。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'注意事项：  ' + NCHAR(13) + NCHAR(10) + N'- ❗ 本工具为**安全只读操作**，不修改任何业务数据；  ' + NCHAR(13) + NCHAR(10) + N'- ❗ 不应与 `create_supplier_from_file`、`update_supplier` 等写入类工具混淆；  ' + NCHAR(13) + NCHAR(10) + N'- ❗ 返回的 `files` 仅用于下载模板，**不能用于创建供应商**（因模板为空）；  ' + NCHAR(13) + NCHAR(10) + N'- 建议前端在用户点击“下载模板”按钮时直接调用此工具。',
        InputSchemaJson = N'{"type":"object","properties":{}}', Risk = N'Unknown',
        Sha256 = N'3a197c4a33ccb1b7bf5a8b0683c06b5a7f9c6e6d0e8a28ee96ef41cf1314b2c4', DiscoveredAtUtc = CONVERT(datetime2(7), N'2026-07-29T03:17:11.9490146', 126)
