        InputSchemaJson = N'{"type":"object","properties":{"supplierId":{"type":"string","description":"\u4F9B\u5E94\u5546\u552F\u4E00\u6807\u8BC6"},"supplierNo":{"type":"string","description":"\u4F9B\u5E94\u5546\u7F16\u53F7"}}}', Risk = N'Unknown',
        Sha256 = N'3083d54e53c14825d085aa76b0bc7b3ad23ad5e353e28fe0f7ac41a8fe2ad7c2', DiscoveredAtUtc = CONVERT(datetime2(7), N'2026-07-29T03:17:11.9490146', 126)
