    UPDATE dbo.AgMcpToolVersion
    SET ServerId = CONVERT(uniqueidentifier, N'4ca452c6-088b-421d-91ed-9f9f418b488b'), HistoryOrdinal = 7, CurrentOrdinal = 1,
        Name = N'create_supplier_from_file', Description = CAST(N'' AS nvarchar(max)) + N'工具名称：create_supplier_from_file' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'功能描述：' + NCHAR(13) + NCHAR(10) + N'仅当用户明确表示希望通过**已上传的文件**（如 Excel、CSV 等）**批量或自动创建新供应商**时，才调用此工具。  ' + NCHAR(13) + NCHAR(10) + N'该工具会根据提供的文件标识（fileId）解析文件内容，并在系统中创建对应的供应商记录。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'输入参数：' + NCHAR(13) + NCHAR(10) + N'- fileId（字符串，必填）：由文件上传服务返回的、已成功上传的文件唯一标识。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'触发条件（必须同时满足）：' + NCHAR(13) + NCHAR(10) + N'- 用户意图是**创建/新增/导入**供应商（而非查看、查询、获取、编辑）；' + NCHAR(13) + NCHAR(10) + N'- 用户明确提及**文件、上传、导入、批量、模板、Excel、CSV**等关键词；' + NCHAR(13) + NCHAR(10) + N'- 用户提供了或系统上下文中存在有效的 fileId。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'行为说明：' + NCHAR(13) + NCHAR(10) + N'- 工具将解析文件并校验数据（如必填字段、唯一性约束等）；' + NCHAR(13) + NCHAR(10) + N'- 若校验失败（如格式错误、缺少字段、编码重复等），返回具体错误原因；' + NCHAR(13) + NCHAR(10) + N'- 创建成功后，返回新供应商 ID 及前端跳转模块（如 BD_SUPPLIER_DETAIL）。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'注意事项：' + NCHAR(13) + NCHAR(10) + N'- ❗ 本工具为**数据写入操作**，不可用于查询、查看或获取已有供应商信息；' + NCHAR(13) + NCHAR(10) + N'- ❗ 若用户仅说“获取供应商”“查看供应商列表”“查一下供应商”，**绝对不应调用此工具**；' + NCHAR(13) + NCHAR(10) + N'- ❗ 请勿与仅用于打开表单页面的 create_supplier 或用于查询的 get_supplier 工具混淆；' + NCHAR(13) + NCHAR(10) + N'- 调用前必须确认 fileId 有效且用户有权限访问该文件。',
        InputSchemaJson = N'{"type":"object","properties":{"fileId":{"type":"string","description":"\u6587\u4EF6ID"}}}', Risk = N'Mutating',
        Sha256 = N'e25eacd0dab40aee4c247d173aee88591f4c5b9306936c5fab6c44dcaff123f8', DiscoveredAtUtc = CONVERT(datetime2(7), N'2026-07-29T03:18:54.0556948', 126)
