        InputSchemaJson = N'{"type":"object","properties":{"supplierId":{"type":"string","description":"\u4F9B\u5E94\u5546\u552F\u4E00\u6807\u8BC6"},"supplierNo":{"type":"string","description":"\u4F9B\u5E94\u5546\u7F16\u53F7"}}}', Risk = N'Mutating',
